using System;using System.IO;using System.Windows.Forms;using System.Web.Script.Serialization;using System.Collections.Generic;using ConfidenceDesktop;
class PortableSetup{
[STAThread]static void Main(string[] args){string settings=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"商店套装设置.json");if(args.Length>0&&args[0]=="--auto"){try{GameLocation.SaveDetected(settings);}catch{}return;}Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{if(GameLocation.SaveDetected(settings)){MessageBox.Show("已检测并保存游戏目录。请重新打开小助手。","设置完成");return;}}catch{}using(var dialog=new OpenFileDialog{Title="未能确定游戏目录，请选择 Game 文件夹内的 League of Legends.exe",Filter="英雄联盟游戏程序|League of Legends.exe",CheckFileExists=true}){if(dialog.ShowDialog()!=DialogResult.OK)return;string dir=GameLocation.Normalize(dialog.FileName);if(dir==null)return;var json=new JavaScriptSerializer();var config=File.Exists(settings)?json.Deserialize<Dictionary<string,object>>(File.ReadAllText(settings)):new Dictionary<string,object>{{"maxArchetypeGap",.03}};config["enabled"]=true;config["gameDirectory"]=dir;File.WriteAllText(settings,json.Serialize(config),new System.Text.UTF8Encoding(false));MessageBox.Show("游戏目录已保存，请重新打开小助手。","设置完成");}}
}
